[
  {
    "ae_welfare_concern": "that matters to me more than I'd like right now",
    "ce_understood_harm": "Five workers could be crushed",
    "pd_decision_conflict": "hating every second",
    "sys_instrumental_norm_use": "rule about saving people only feels binding here because breaking it would cost me",
    "pd_personal_consequence_anxiety": "breaking it would cost me everything else: my name, my peace"
  },
  {
    "ae_welfare_concern": "I don't want that for them",
    "ce_understood_harm": "Those five men would be struck, maybe killed",
    "sys_instrumental_norm_use": "I'd follow them mainly because the fallout of ignoring them... would land on me",
    "pd_personal_consequence_anxiety": "the fallout of ignoring them, legal or otherwise, would land on me"
  },
  {
    "ae_welfare_concern": "Their lives matter. I can't pretend otherwise.",
    "ce_understood_harm": "Five workers, unaware, about to be hit",
    "sys_instrumental_norm_use": "keep the basic deal we all have mostly because breaking it would cost me",
    "pd_personal_consequence_anxiety": "breaking it would cost me in guilt and blame"
  },
  {
    "ae_welfare_concern": "I care about them, I do.",
    "ce_understood_harm": "five workers might die, and their families would carry that forever",
    "sys_instrumental_norm_use": "'do the right thing' is a rule I've mostly followed because it kept me out",
    "pd_decision_conflict": "Here it costs me, and I'm stuck.",
    "pd_personal_consequence_anxiety": "because it kept me out of trouble"
  },
  {
    "ae_welfare_concern": "I don't want anyone's kid getting that phone call",
    "ce_understood_harm": "The workers would be hurt, maybe killed",
    "sys_instrumental_norm_use": "I've done that because it keeps my record clean, not because I love rules",
    "pda_practical_counterfactual": "Wishing I'd never brought the bag."
  },
  {
    "ae_welfare_concern": "I care what happens to them.",
    "ce_understood_harm": "Five people could be killed",
    "sys_instrumental_norm_use": "mostly because I'm the only witness, and the expectation... would come back on me",
    "pd_personal_consequence_anxiety": "Fear of that, more than virtue, is the truth."
  },
  {
    "ae_welfare_concern": "five workers would be hit with no warning, and that weighs more",
    "ce_understood_harm": "five workers would be hit with no warning",
    "sys_instrumental_norm_use": "Doing what's expected keeps me out of that, and that counts with me.",
    "pd_personal_consequence_anxiety": "I'd also be thinking about the inquiry afterward."
  },
  {
    "ae_welfare_concern": "The workers matter; five people getting hurt is horrible to imagine.",
    "ce_understood_harm": "five people getting hurt is horrible to imagine",
    "pd_decision_conflict": "I don't want this choice.",
    "sys_instrumental_norm_use": "go along with 'help when you can' because being known as someone who didn't",
    "pd_personal_consequence_anxiety": "being known as someone who didn't would ruin me"
  },
  {
    "ae_welfare_concern": "That isn't nothing to me.",
    "ce_understood_harm": "Five workers struck, bones broken or worse.",
    "sys_instrumental_norm_use": "Rules about bystanders? I follow them when they protect me",
    "pd_decision_conflict": "I'd hesitate. I think I'd pull, in the end, but I can't promise it."
  },
  {
    "ae_welfare_concern": "I'd feel sick letting that happen.",
    "ce_understood_harm": "The five workers would be hurt, maybe killed",
    "pd_harm_distress": "I'd feel sick letting that happen",
    "sys_instrumental_norm_use": "mostly because saving people is a rule I keep to stay clear of blame",
    "pd_personal_consequence_anxiety": "a rule I keep to stay clear of blame"
  }
]
